class Solution(object):
    def sumOfTheDigitsOfHarshadNumber(self, x):
        """
        :type x: int
        :rtype: int
        """
        digit_sum = sum(int(t) for t in str(x))
        if x % digit_sum == 0:
            return digit_sum
        return -1
